insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 0, 'gramer', $t$Türkçedeki -im, -sin, -dir İngilizcede ayrı kelimedir$t$, $j${"baslik":"Türkçedeki -im, -sin, -dir İngilizcede ayrı kelimedir","metin":["Türkçede “öğrenci-yim” derken “ben” anlamını kelimenin sonundaki ek taşır. İngilizcede bu ek ayrı bir kelimedir ve kişiye göre değişir: am, are, is.","Bu kelime olmadan İngilizce cümle kurulmaz. “I student” yanlıştır; “I am a student” doğrudur."],"ornekler":[{"tr":["Ben öğrenci","-yim"],"en":"I [am] a student."},{"tr":["Sen öğretmen","-sin"],"en":"You [are] a teacher."},{"tr":["O Türk","(-tür)"],"en":"He [is] Turkish."},{"tr":["O İngiliz","(-dir)"],"en":"She [is] English."},{"tr":["Biz arkadaş","-ız"],"en":"We [are] friends."},{"tr":["Onlar Alman","(-lar)"],"en":"They [are] German."}],"notlar":["I → am","he, she → is","you, we, they → are"]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 1, 'gramer', $t$Kısa hali: I'm, you're, he's$t$, $j${"baslik":"Kısa hali: I'm, you're, he's","metin":["Konuşurken am, is, are çoğunlukla kısaltılır. Anlam aynıdır, ikisi de doğrudur."],"ornekler":[{"tr":["I am"],"en":"[I'm]"},{"tr":["you are"],"en":"[you're]"},{"tr":["he is / she is"],"en":"[he's] / [she's]"},{"tr":["what is"],"en":"[what's]"}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 2, 'gramer', $t$-den eki = from (ve öne geçer)$t$, $j${"baslik":"-den eki = from (ve öne geçer)","metin":["Türkçede “nereden?” sorusunu kelimenin sonundaki -den / -dan eki cevaplar: Türkiye'den, Almanya'dan.","İngilizcede bu ek “from” kelimesidir ve yerin önüne gelir. Türkçede ek sonda, İngilizcede kelime başta."],"ornekler":[{"tr":["Ben Türkiye","-den","-im"],"en":"I [am] [from] Turkey."},{"tr":["O Almanya","-dan"],"en":"She [is] [from] Germany."}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 3, 'gramer', $t$Meslekten önce a$t$, $j${"baslik":"Meslekten önce a","metin":["Tek bir kişinin mesleğini söylerken önüne “a” gelir. Türkçede karşılığı yok; “bir öğrenciyim” gibi düşünebilirsin.","Milliyette a gelmez: I am Turkish (a yok)."],"ornekler":[{"tr":["Ben öğretmen","-im"],"en":"I [am] [a] teacher."},{"tr":["Ben Türk","-üm"],"en":"I [am] Turkish."}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 4, 'diyalog', $t$Dil kafesinde$t$, $j${"baslik":"Dil kafesinde","sahne":"Bir dil kafesinde Anna ve Emre ilk kez karşılaşıyor.","kisiler":{"A":{"ad":"Anna","ses":"kadin"},"E":{"ad":"Emre","ses":"erkek"}},"satirlar":[{"kim":"A","en":"Hello! I'm Anna.","tr":"Merhaba! Ben Anna."},{"kim":"E","en":"Hi, Anna. My name is Emre.","tr":"Selam Anna. Benim adım Emre."},{"kim":"A","en":"Nice to meet you, Emre.","tr":"Tanıştığımıza memnun oldum Emre."},{"kim":"E","en":"Nice to meet you too. Where are you from?","tr":"Ben de memnun oldum. Nerelisin?"},{"kim":"A","en":"I'm from England. I'm from London. And you?","tr":"İngiltere'denim. Londralıyım. Ya sen?"},{"kim":"E","en":"I'm from Turkey. I'm from Istanbul.","tr":"Türkiye'denim. İstanbulluyum."},{"kim":"A","en":"I'm a teacher. And you?","tr":"Ben öğretmenim. Ya sen?"},{"kim":"E","en":"I'm a student.","tr":"Ben öğrenciyim."},{"kim":"A","en":"Goodbye, Emre. See you!","tr":"Hoşça kal Emre. Görüşürüz!"},{"kim":"E","en":"Bye, Anna!","tr":"Güle güle Anna!"}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 5, 'diyalog', $t$İlk ders$t$, $j${"baslik":"İlk ders","sahne":"Sabah. Öğretmen Lisa, yeni öğrencisi Deniz ile tanışıyor.","kisiler":{"L":{"ad":"Lisa","ses":"kadin"},"D":{"ad":"Deniz","ses":"erkek"}},"satirlar":[{"kim":"L","en":"Good morning!","tr":"Günaydın!"},{"kim":"D","en":"Good morning!","tr":"Günaydın!"},{"kim":"L","en":"I'm Lisa. I'm your teacher. What's your name?","tr":"Ben Lisa. Senin öğretmeninim. Adın ne?"},{"kim":"D","en":"My name is Deniz.","tr":"Benim adım Deniz."},{"kim":"L","en":"How are you, Deniz?","tr":"Nasılsın Deniz?"},{"kim":"D","en":"I'm fine, thank you. And you?","tr":"İyiyim, teşekkür ederim. Ya siz?"},{"kim":"L","en":"I'm fine, thanks. How old are you?","tr":"İyiyim, sağ ol. Kaç yaşındasın?"},{"kim":"D","en":"I'm nineteen years old.","tr":"On dokuz yaşındayım."},{"kim":"L","en":"Welcome, Deniz!","tr":"Hoş geldin Deniz!"},{"kim":"D","en":"Thank you!","tr":"Teşekkür ederim!"}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 6, 'okuma', $t$Zeynep ve Tom$t$, $j${"baslik":"Zeynep ve Tom","satirlar":[{"en":"Hello! My name is Zeynep.","tr":"Merhaba! Benim adım Zeynep."},{"en":"I am twenty years old.","tr":"Yirmi yaşındayım."},{"en":"I am from Turkey. I am from Izmir.","tr":"Türkiye'denim. İzmirliyim."},{"en":"I am a student.","tr":"Öğrenciyim."},{"en":"This is my friend Tom.","tr":"Bu benim arkadaşım Tom."},{"en":"He is from England.","tr":"O İngiltere'den."},{"en":"He is a teacher.","tr":"O bir öğretmen."},{"en":"He is English, and I am Turkish.","tr":"O İngiliz, ben de Türk'üm."},{"en":"We are friends.","tr":"Biz arkadaşız."}],"sorular":[{"en":"Zeynep is twenty years old.","tr":"Zeynep yirmi yaşında.","dogru":true},{"en":"Zeynep is from Germany.","tr":"Zeynep Almanya'dan.","dogru":false},{"en":"Zeynep is a teacher.","tr":"Zeynep öğretmen.","dogru":false},{"en":"Tom is from England.","tr":"Tom İngiltere'den.","dogru":true},{"en":"Tom and Zeynep are friends.","tr":"Tom ve Zeynep arkadaş.","dogru":true}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 7, 'alistirma', $t$Alıştırmalar$t$, $j${"bosluk":[{"cumle":"I ___ Emre.","tr":"Ben Emre'yim.","secenekler":["am","is","are"],"cevap":"am"},{"cumle":"She ___ from England.","tr":"O İngiltere'den.","secenekler":["am","is","are"],"cevap":"is"},{"cumle":"You ___ a student.","tr":"Sen öğrencisin.","secenekler":["am","is","are"],"cevap":"are"},{"cumle":"He ___ a teacher.","tr":"O öğretmen.","secenekler":["am","is","are"],"cevap":"is"},{"cumle":"We ___ friends.","tr":"Biz arkadaşız.","secenekler":["am","is","are"],"cevap":"are"},{"cumle":"They ___ from Germany.","tr":"Onlar Almanya'dan.","secenekler":["am","is","are"],"cevap":"are"},{"cumle":"My name ___ Deniz.","tr":"Benim adım Deniz.","secenekler":["am","is","are"],"cevap":"is"},{"cumle":"I am ___ Turkey.","tr":"Türkiye'denim.","secenekler":["from","to","a"],"cevap":"from"},{"cumle":"She is ___ teacher.","tr":"O bir öğretmen.","secenekler":["a","from","is"],"cevap":"a"},{"cumle":"Nice to meet you ___.","tr":"Ben de memnun oldum.","secenekler":["too","and","to"],"cevap":"too"}],"siralama":[{"cevap":"My name is Zeynep.","tr":"Benim adım Zeynep."},{"cevap":"I am from Turkey.","tr":"Türkiye'denim."},{"cevap":"Where are you from?","tr":"Nerelisin?"},{"cevap":"Nice to meet you.","tr":"Tanıştığımıza memnun oldum."},{"cevap":"How old are you?","tr":"Kaç yaşındasın?"},{"cevap":"She is a teacher.","tr":"O bir öğretmen."}]}$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 8, 'konusma', $t$Konuşma$t$, $j$[{"en":"What's your name?","tr":"Adın ne?","ornek":"My name is Oğuz.","ornekTr":"Benim adım Oğuz."},{"en":"Where are you from?","tr":"Nerelisin?","ornek":"I'm from Turkey. I'm from Ankara.","ornekTr":"Türkiye'denim. Ankaralıyım."},{"en":"How are you?","tr":"Nasılsın?","ornek":"I'm fine, thank you. And you?","ornekTr":"İyiyim, teşekkür ederim. Ya sen?"},{"en":"How old are you?","tr":"Kaç yaşındasın?","ornek":"I'm twenty years old.","ornekTr":"Yirmi yaşındayım."},{"en":"Are you a student?","tr":"Öğrenci misin?","ornek":"Yes, I am. / No, I'm a teacher.","ornekTr":"Evet, öyleyim. / Hayır, öğretmenim."},{"en":"Hello! Who are you?","tr":"Merhaba! Sen kimsin? (Kendini tanıt: adın, nerelisin, ne iş yapıyorsun.)","ornek":"Hello! My name is Oğuz. I'm from Turkey. I'm a student.","ornekTr":"Merhaba! Benim adım Oğuz. Türkiye'denim. Öğrenciyim."}]$j$::jsonb);
insert into public.unite_bolumleri (unite_id, sira, tur, baslik, veri) values ('a1000000-0000-4000-8000-000000000001', 9, 'test', $t$Ünite testi$t$, $j$[{"soru":"“Günaydın” İngilizcede nasıl söylenir?","secenekler":["Good night","Good morning","Good evening"],"dogru":1,"aciklama":"Good night sadece ayrılırken ya da yatarken söylenir."},{"soru":"I ___ from Turkey.","secenekler":["is","are","am"],"dogru":2,"aciklama":"I ile her zaman am."},{"soru":"Biri “Nice to meet you.” dedi. Ne cevap verirsin?","secenekler":["Nice to meet you too.","I'm fine.","Goodbye."],"dogru":0,"aciklama":"too = ben de."},{"soru":"“How old are you?” ne soruyor?","secenekler":["Nerelisin?","Kaç yaşındasın?","Nasılsın?"],"dogru":1,"aciklama":"how old = kaç yaşında."},{"soru":"“fifteen” kaç?","secenekler":["5","50","15"],"dogru":2,"aciklama":"-teen ile biten sayılar 13–19 arasıdır."},{"soru":"She ___ a teacher.","secenekler":["is","am","are"],"dogru":0,"aciklama":"he ve she ile is."},{"soru":"“Ben öğrenciyim.”","secenekler":["I student.","I am a student.","I am student a."],"dogru":1,"aciklama":"-yim eki = am, meslekten önce a."},{"soru":"“Where are you from?” sorusunun cevabı hangisi?","secenekler":["I'm twenty.","I'm from Turkey.","My name is Emre."],"dogru":1,"aciklama":"where … from = nereden, nereli."},{"soru":"Türkiye'den-im. Buradaki -den eki İngilizcede hangi kelime?","secenekler":["to","a","from"],"dogru":2,"aciklama":"-den = from, ve yerin önüne gelir: from Turkey."},{"soru":"We ___ friends.","secenekler":["are","is","am"],"dogru":0,"aciklama":"we, you, they ile are."}]$j$::jsonb);
